class JvmComponents {
    private final int base;

    JvmComponents(int base) {
        this.base = base;
    }

    int add(int value) {
        int result = base + value; // value and result belong to this invocation's frame
        return result;
    }

    public static void main(String[] args) {
        JvmComponents object = new JvmComponents(40);
        System.out.println(object.add(2));
    }
}
